DROP TABLE IF EXISTS `wf_process_config`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `wf_process_config` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL COMMENT '租户ID【多租户隔离字段】',
  `biz_type` varchar(50) NOT NULL COMMENT '业务单据类型:EXP_APPLY/EXP_CLAIM/EXP_LOAN/EXP_REPAY/EXP_PAY/BG_ADJUST',
  `sub_type` varchar(32) DEFAULT NULL COMMENT '单据子类型(TRAVEL/SETTLE/PREPAY…)：NULL=通配，非空=精确优先(V1.3.19)',
  `config_name` varchar(200) NOT NULL COMMENT '配置名称',
  `model_key` varchar(64) NOT NULL COMMENT '绑定的流程定义key',
  `company_id` bigint DEFAULT NULL COMMENT '适用公司,空表示全租户',
  `dept_id` bigint DEFAULT NULL COMMENT '适用部门,空表示不限',
  `amount_min` decimal(20,2) DEFAULT NULL COMMENT '金额下限(含),空表示不限',
  `amount_max` decimal(20,2) DEFAULT NULL COMMENT '金额上限(不含),空表示不限',
  `condition_expr` varchar(1000) DEFAULT NULL COMMENT '额外条件表达式(SpEL),如 #bill.urgent == true',
  `priority` int NOT NULL DEFAULT '0' COMMENT '优先级,数值大者优先命中',
  `status` varchar(20) NOT NULL DEFAULT 'NORMAL' COMMENT '状态:NORMAL/DISABLED',
  `remark` varchar(500) DEFAULT NULL,
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_tenant` (`tenant_id`),
  KEY `idx_tenant_biz` (`tenant_id`,`biz_type`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=296 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='单据类型流程绑定配置';
/*!40101 SET character_set_client = @saved_cs_client */;

